{
  "name": "opencode-ultra",
  "version": "0.9.9",
  "description": "Lightweight OpenCode 1.2.x plugin — ultrawork mode, multi-agent orchestration, rules injection",
  "keywords": [
    "opencode",
    "plugin",
    "orchestration",
    "multi-agent",
    "ultrawork"
  ],
  "homepage": "https://github.com/ouchanip/opencode-ultra#readme",
  "bugs": {
    "url": "https://github.com/ouchanip/opencode-ultra/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ouchanip/opencode-ultra.git"
  },
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm && tsc --emitDeclarationOnly --outDir dist 2>/dev/null || true",
    "test": "bun test",
    "dev": "bun run --watch src/index.ts"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.19",
    "@opencode-ai/sdk": "^1.1.19",
    "jsonc-parser": "^3.3.1",
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "^5.8.0"
  },
  "files": [
    "dist"
  ],
  "license": "SEE LICENSE IN LICENSE.md"
}
